
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_xc_pwb6k_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_pwb6k", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.411153823476975e+00, -2.366795657286130e+00, -2.304669058600938e+00, -2.218669691931408e+00, -2.101609267975822e+00, -1.946057064313485e+00, -1.746303056928545e+00, -1.501782517882782e+00, -1.221239482991819e+00, -9.234601841907701e-01, -6.285467046084376e-01, -4.401211432246398e-01, -3.650984361611889e-01, -2.991933824152064e-01, -2.187955165245621e-01, -1.396919700566127e-01, -7.308976525551560e-02, -1.153828142488331e-02, -1.035504527354206e-04, -1.141713718573650e-07]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


